//! MLIR-to-GPU (CUDA C) translator for NVIDIA GPU targets.
//!
//! Converts merged MLIR modules (LLVM dialect with `__tile_*` intrinsics)
//! into CUDA C source (`.cu` file) that can be compiled with `nvcc` or
//! `clang++ --cuda-gpu-arch=sm_80`.
//!
//! # CUDA C Output Format
//!
//! A typical generated kernel looks like:
//!
//! ```cuda
//! // Generated by tile-rs mlir_to_gpu — DO NOT EDIT
//! // Compile: nvcc -arch=sm_80 -O3 tile_softmax.gpu.cu -o tile_softmax.ptx --ptx
//!
//! #include <cuda_runtime.h>
//! #include <math.h>
//! #include <stdint.h>
//!
//! __device__ __forceinline__ float warp_reduce_max(float val) {
//!     for (int offset = 16; offset > 0; offset >>= 1)
//!         val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
//!     return val;
//! }
//!
//! // tile_softmax: rows=1, cols=1024
//! // Launch: <<<num_tiles, 1024>>>
//! __global__ void tile_softmax(const float* __restrict__ p0, float* __restrict__ p1) { ... }
//! ```
//!
//! # Mapping from tile_std tile intrinsics to CUDA ops
//!
//! | tile_std intrinsic | CUDA kernel pattern |
//! |---|---|
//! | `__tile_load_f32(gm, rows, cols)` | `p0[goff]` element load |
//! | `__tile_store_f32(gm, buf, rows, cols)` | `p1[goff] = val` element store |
//! | `__tile_add_f32(0, a, b, rows, cols)` | `out[goff] = in0[goff] + in1[goff]` |
//! | `__tile_sub_f32(0, a, b, rows, cols)` | `out[goff] = in0[goff] - in1[goff]` |
//! | `__tile_mul_f32(0, a, b, rows, cols)` | `out[goff] = in0[goff] * in1[goff]` |
//! | `__tile_exp_f32(0, src, rows, cols)` | `out[goff] = expf(in[goff])` |
//! | `__tile_softmax_f32(0, src, rows, cols)` | 5-step warp+shared-mem reduction |
//! | `__tile_reduce_max_f32(0, src, rows, cols)` | warp reduce → scalar per block |
//! | `__tile_reduce_sum_f32(0, src, rows, cols)` | same pattern |
//! | `__tile_scale_f32(0, src, scalar, rows, cols)` | `out[goff] = in[goff] * scalar` |
//! | `__tile_matmul_f32(0, a, b, m, k, n)` | TODO: cublasSgemm (emitted as comment) |

use std::collections::HashMap;
use std::fmt::Write;

use crate::mlir_parse::{emit_unrolled_k_accumulation, DEFAULT_K_UNROLL};
use crate::mlir_to_pto::{
    FuncArg, MlirFunc, extract_call_args, extract_result_ssa, infer_arg_dtype_from_body,
    infer_dtype_from_name, is_builtin_helper, parse_const_arg, parse_module,
};

/// A GM argument's element type: what the BODY does with it, falling back to
/// what it is called.
///
/// The name alone is not enough and the repo already knows it. `mlir_to_pto`
/// carries `infer_arg_dtype_from_body` for exactly this reason — its comment
/// records an f16 GEMM that emitted `!pto.ptr<f32>` in the signature while the
/// tensor views said `f16`, and quotes the ptoas diagnostic that refused it.
///
/// This emitter had kept the name-only inference. An f16 kernel whose Rust arg
/// names do not happen to contain "f16" — `fn matmul(a: *const f16, b: *const
/// f16, out: *mut f16)` is the shape the PTO comment names — emitted
/// `const float* __restrict__` for half-precision buffers.
///
/// HOW BADLY THAT BITES DEPENDS ON THE CALLER, and it is worth being exact.
/// A typed C++ caller is safe: nvcc refuses `__half*` against `const float*`
/// outright, which is what happens if the kernel is driven from a `.cu`
/// harness. The host that actually drives these kernels does not get that
/// protection — `ds4_cuda`'s FFI passes device pointers as `*mut c_void`
/// across 41 entry points, so nothing checks the element type and the kernel
/// reads pairs of halves as single floats. Ascend was protected by ptoas
/// refusing the signature; CUDA is protected only where the caller happens to
/// be typed.
fn gm_arg_dtype(arg: &FuncArg, body_lines: &[String]) -> &'static str {
    infer_arg_dtype_from_body(&arg.name, body_lines)
        .unwrap_or_else(|| infer_dtype_from_name(&arg.name))
}

/// CUDA keeps the receipted default; the optimum is target-specific.
const MATMUL_TRANSPOSED_K_UNROLL: usize = DEFAULT_K_UNROLL;

