    #[test]
    fn test_gpu_gemm_is_2d_tiled() {
        let cu = convert_mlir_to_gpu(&square_gemm_mlir(1024)).unwrap();

        // 2D launch contract, one block per BM x BN patch. Derived from the
        // geometry: the grid is (N/BN, M/BM) and the block is one thread per
        // TM x TN micro-tile. Hardcoding dim3(16, 16) silently stopped describing
        // the emitter when the block tile went 64x64 -> 128x64.
        let launch = format!("// Launch: <<<dim3({}, {}), {GEMM_BLOCK}>>>",
                             1024 / GEMM_BN, 1024 / GEMM_BM);
        assert!(
            cu.contains(&launch),
            "tiled GEMM must declare a 2D grid over output patches:\n{}",
            cu
        );
        assert!(
            cu.contains("__launch_bounds__(256) __global__ void mm"),
            "tiled GEMM block is one thread per micro-tile:\n{}",
            cu
        );

        // Operands are staged through shared memory, and A transposed so the
        // inner loop walks it along BM.
        // A is staged [BK][BM] and B [BK][BN], so A followed the tile to
        // [16][128] when BM went 64 -> 128 and B did not move. Derived, because
        // the two used to be spelled identically and a reader could not tell
        // which one was supposed to track BM.
        assert!(
            cu.contains(&format!("__shared__ float _As[{GEMM_BK}][{GEMM_BM}];"))
                && cu.contains(&format!("__shared__ float _Bs[{GEMM_BK}][{GEMM_BN}];")),
            "tiled GEMM must stage both operands in shared memory:\n{}",
            cu
        );

        // Per-thread register accumulator, and no per-output k loop left.
        assert!(
            cu.contains(&format!("float _gemm_acc[{GEMM_TM}][{GEMM_TN}];")),
            "each thread must hold a 4x4 accumulator:\n{}",
            cu
        );
        assert!(
            !cu.contains("_mm_acc"),
            "the naive per-output k loop must be gone:\n{}",
            cu
        );

        // The loads that only fed the matmul are dead here — emitting them
        // would index A and B with C's goff, which is out of bounds whenever
        // K < N.
        assert!(
            !cu.contains("float _v0 = p0[goff];"),
            "operand loads feeding the matmul must not be emitted:\n{}",
            cu
        );

        // Output nest binds each accumulator element to one goff, so the rest
        // of the statement stream is unchanged.
        assert!(
            cu.contains("const int goff = (_oRow + _i) * 1024 + _oCol + _j;")
                && cu.contains("p2[goff] = _gemm_acc[_i][_j];"),
            "output nest must map the accumulator through goff:\n{}",
            cu
        );
    }

    /// The tiled grid is only (M/BM)*(N/BN) blocks, so a small matmul leaves
    /// the device idle and loses to the naive form — measured 0.60x at 4 blocks
    /// on 48 SMs. Below the guard the naive lowering stays.
    ///
    /// This test also pins the band that the 64x64 -> 128x64 tile change moved
    /// (see GEMM_MIN_BLOCKS). 256^3 tiled when a block was 64x64 and measured
    /// 1.50x there; the same shape now yields 8 blocks and falls back. That is a
    /// missed win rather than a wrong answer, and it is UNMEASURED under the new
    /// geometry — so assert it as the emitter's current behaviour, with the
    /// number that would have to be beaten if someone puts this on a GB10 again.
    #[test]
    fn test_gpu_small_gemm_keeps_naive_lowering() {
        let blocks = |d: u32| (d / GEMM_BM) * (d / GEMM_BN);

        let cu = convert_mlir_to_gpu(&square_gemm_mlir(128)).unwrap();
        assert!(blocks(128) < GEMM_MIN_BLOCKS, "128^3 must be under the guard");
        assert!(
            !cu.contains("_gemm_acc"),
            "128^3 is only {} blocks — must not take the tiled path:\n{}",
            blocks(128),
            cu
        );
        assert!(
            cu.contains("float _mm_acc = 0.0f;"),
            "small GEMM must keep the naive lowering:\n{}",
            cu
        );

        // The engagement point, derived rather than hardcoded. A shape at or
        // above the guard tiles; one below it does not.
        let d = (1..=64u32)
            .map(|i| i * GEMM_BM)
            .find(|&d| blocks(d) >= GEMM_MIN_BLOCKS)
            .expect("some square shape reaches the guard");
        let big = convert_mlir_to_gpu(&square_gemm_mlir(d)).unwrap();
        assert!(
            big.contains("_gemm_acc"),
            "{d}^3 is {} blocks and should tile:\n{}",
            blocks(d),
            big
        );

        // 256^3 sits in the band the tile change moved: 16 blocks and a measured
        // 1.50x under 64x64, 8 blocks and naive under 128x64. Pinned so the
        // regression is visible rather than silent; flip it only with a number.
        assert!(blocks(256) < GEMM_MIN_BLOCKS, "256^3 is under the guard today");
        let mid = convert_mlir_to_gpu(&square_gemm_mlir(256)).unwrap();
        assert!(
            !mid.contains("_gemm_acc"),
            "256^3 falls back today ({} blocks); tiling it again needs a GB10 \
             number beating the naive form, not a threshold edit:\n{}",
            blocks(256),
            mid
        );
    }

    /// The point of routing the accumulator through `goff` rather than
    /// special-casing matmul: an op fused after the matmul reads it like any
    /// other tile variable, with no knowledge of the index space.
    #[test]
    fn test_gpu_gemm_fuses_with_following_elementwise() {
        let mlir = r#"
module {
  llvm.func @mm_silu(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>, %arg2: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %d = llvm.mlir.constant(512 : i32) : i32
    %a = llvm.call @__tile_load_f32(%arg0, %d, %d) : (!llvm.ptr<1>, i32, i32) -> i32
    %b = llvm.call @__tile_load_f32(%arg1, %d, %d) : (!llvm.ptr<1>, i32, i32) -> i32
    %y = llvm.call @__tile_matmul_f32(%a, %a, %b, %d, %d, %d) : (i32, i32, i32, i32, i32, i32) -> i32
    %s = llvm.call @__tile_silu_f32(%y, %y, %d, %d) : (i32, i32, i32, i32) -> i32
    llvm.call @__tile_store_f32(%arg2, %s, %d, %d) : (!llvm.ptr<1>, i32, i32, i32) -> ()
    llvm.return
  }
}
"#;
        let cu = convert_mlir_to_gpu(mlir).unwrap();
        // This assertion and `warp_area_is_the_rule_not_tile_count` pin the SAME
        // property, so it stays exact rather than being relaxed to `_gemm_acc[`.
        // The VALUE moved 4x4 -> 8x4 because the block tile was raised to 128x64,
        // which is a measured win (1.17x on a GB10, see that test), not the drift
        // toward the measured-bad 2048 area that this pair exists to catch.
        // Derived from the constants so the pair cannot fall out of step again.
        assert!(cu.contains(&format!("_gemm_acc[{GEMM_TM}][{GEMM_TN}]")),
                "should tile:\n{}", cu);
        // The silu consumes the accumulator element, inside the output nest.
        assert!(
            cu.contains("_gemm_acc[_i][_j]") && cu.contains("expf(-"),
            "elementwise fused after the matmul must read the accumulator:\n{}",
            cu
        );
        assert!(
            !cu.contains("_mm_acc"),
            "must not fall back to the naive lowering:\n{}",
            cu
        );
    }

    #[test]
    fn test_gpu_wide_tile_is_launchable() {
        let wide_mlp = r#"
module {
  llvm.func @wide_mlp(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>, %arg2: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %r = llvm.mlir.constant(1 : i32) : i32
    %c = llvm.mlir.constant(8960 : i32) : i32
    %g = llvm.call @__tile_load_f32(%arg0, %r, %c) : (!llvm.ptr<1>, i32, i32) -> i32
    %u = llvm.call @__tile_load_f32(%arg1, %r, %c) : (!llvm.ptr<1>, i32, i32) -> i32
    %s = llvm.call @__tile_silu_f32(%g, %g, %r, %c) : (i32, i32, i32, i32) -> i32
    %y = llvm.call @__tile_mul_f32(%s, %s, %u, %r, %c) : (i32, i32, i32, i32, i32) -> i32
    llvm.call @__tile_store_f32(%arg2, %y, %r, %c) : (!llvm.ptr<1>, i32, i32, i32) -> ()
    llvm.return
  }
}
"#;
        let cu = convert_mlir_to_gpu(wide_mlp).unwrap();
        assert!(
            cu.contains("// Launch: <<<num_tiles, 1024>>>"),
            "wide tile must be launched at a legal block width:\n{}",
            cu
        );
        assert!(
            cu.contains("for (int col = tid; col < 8960; col += 1024)"),
            "wide tile must be walked column-strided:\n{}",
            cu
        );
        assert!(
            cu.contains("__launch_bounds__(1024) __global__ void wide_mlp"),
            "kernel must declare its launch bounds:\n{}",
            cu
        );
    }

    /// A block-wide reduction over a wide tile becomes one pass per reduction
    /// plus a final apply pass, because a strided thread only sees part of the
    /// tile. Softmax reduces twice, so it lowers to three passes.
    #[test]
    fn test_gpu_wide_softmax_is_multipass() {
        let wide_softmax = r#"
module {
  llvm.func @wide_softmax(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %r = llvm.mlir.constant(1 : i32) : i32
    %c = llvm.mlir.constant(1536 : i32) : i32
    %x = llvm.call @__tile_load_f32(%arg0, %r, %c) : (!llvm.ptr<1>, i32, i32) -> i32
    %y = llvm.call @__tile_softmax_f32(%x, %x, %r, %c) : (i32, i32, i32, i32) -> i32
    llvm.call @__tile_store_f32(%arg1, %y, %r, %c) : (!llvm.ptr<1>, i32, i32, i32) -> ()
    llvm.return
  }
}
"#;
        let cu = convert_mlir_to_gpu(wide_softmax).unwrap();
        assert_eq!(
            cu.matches("for (int col = tid; col < 1536; col += 1024)").count(),
            3,
            "wide softmax must lower to max pass, sum pass, apply pass:\n{}",
            cu
        );
        // No marker may survive into the emitted source.
        assert!(
            !cu.contains(REDUCE_MARKER),
            "reduction marker leaked into generated CUDA:\n{}",
            cu
        );
        // The scratch is sized by the block, not the tile.
        assert!(
            cu.contains("__shared__ float sdata[32];"),
            "reduction scratch must be sized per warp of the block:\n{}",
            cu
        );
    }

