    #[test]
    fn test_gpu_rms_norm_block_reduction_large_cols() {
        // cols > 32 must emit block-wide reduction (shared mem + __syncthreads),
        // not a naive warp-only reduce (which would be wrong at cols=1536).
        let mlir = r#"
module {
  llvm.func @tile_rms_large(%arg0: !llvm.ptr<1>, %arg1: !llvm.ptr<1>) attributes {hacc.entry} {
    ^bb0:
    %r = llvm.mlir.constant(1 : i32) : i32
    %c = llvm.mlir.constant(1536 : i32) : i32
    %eps = llvm.mlir.constant(1.0e-6 : f32) : f32
    %src = llvm.call @__tile_load_f32(%arg0, %r, %c) : (!llvm.ptr<1>, i32, i32) -> i32
    %res = llvm.call @__tile_rms_norm_f32(%src, %src, %eps, %r, %c) : (i32, i32, f32, i32, i32) -> i32
    llvm.call @__tile_store_f32(%arg1, %res, %r, %c) : (!llvm.ptr<1>, i32, i32, i32) -> ()
    llvm.return
  }
}
"#;
        let cu = convert_mlir_to_gpu(mlir).unwrap();
        assert!(
            cu.contains("sdata["),
            "block-reduce rms_norm must use sdata:\n{}",
            cu
        );
        assert!(
            cu.contains("__syncthreads()"),
            "block-reduce rms_norm must __syncthreads:\n{}",
            cu
        );
        // The cross-warp result must be broadcast through shared memory. A
        // `__shfl_sync(mask, v, 0)` broadcast only reaches lane 0 of each warp,
        // and only warp 0 holds the block-wide value — every other warp would
        // normalise by its own partial sum (device-confirmed on GB10).
        assert!(
            cu.contains("if (tid == 0) sdata[0] ="),
            "block-reduce rms_norm must publish the block result to sdata[0]:\n{}",
            cu
        );
        assert!(
            !cu.contains("__shfl_sync"),
            "block-reduce rms_norm must NOT broadcast via __shfl_sync:\n{}",
            cu
        );
        assert!(
            cu.contains("rsqrtf"),
            "rms_norm still needs rsqrtf:\n{}",
            cu
        );
    }

