    /// `tile.k_unroll` must change ONLY the unroll factor end-to-end.
    #[test]
    fn test_gpu_matmul_transposed_honours_tile_k_unroll_attr() {
        let mlir = matmul_transposed_mlir().replace(
            "attributes {hacc.entry}",
            "attributes {hacc.entry, tile.k_unroll = 8 : i32}",
        );
        let cu = convert_mlir_to_gpu(&mlir).unwrap();
        assert!(
            cu.contains("_mt_k + 7"),
            "declared tile.k_unroll=8 not honoured:\n{cu}"
        );
        // Default factor-4 HEADER is `_mt_k + 3 <`; +3 alone is also a body
        // offset inside an 8-unroll, so match the header form only.
        assert!(
            !cu.contains("_mt_k + 3 <"),
            "default factor must not leak when schedule is declared:\n{cu}"
        );
        assert!(
            cu.contains("_mt_k + 7 <"),
            "declared factor-8 loop header missing:\n{cu}"
        );
    }

